export function linkExplanation(l){
 if(l.kind==='veth')return 'veth-пара: один конец находится в ядре хоста, второй — как eth0 в сетевом namespace контейнера. Ethernet-кадры передаются между концами; Docker Engine управляет этой парой и мостом, но сам не является промежуточной сетевой картой.';
 if(l.medium==='adapter')return 'Два представления одного виртуального адаптера: net0/virtio у ВМ и eth0/ens18 в гостевой ОС. В симуляторе они связаны явно, чтобы была видна граница гипервизора и гостя. Это не дополнительный физический кабель.';
 if(l.medium==='virtual')return 'Виртуальное соединение внутри хоста. Оно передаёт кадры между указанными виртуальными контактами. Для реальной принадлежности адаптера мосту используйте раздел «Участники моста».';
 if(['smf','mmf','bidi'].includes(l.medium))return 'Оптический физический канал. Совместимость волокна, скорости, TX/RX и длины проверяется. Сами изгибы линии на холсте не имеют сетевого смысла.';
 if(['coax50','coax75'].includes(l.medium))return 'Физический коаксиальный канал. BNC 50 Ω / 10BASE2 и F 75 Ω / MoCA — разные несовместимые среды. Требуется соответствующий активный переход, а не простой разъём.';
 if(l.medium==='copper'||l.medium==='dac')return 'Физический медный Ethernet-канал. Разъём, доступная скорость и длина задаются профилями портов и кабелем. Это двунаправленное соединение.';
 return 'Абстрактный кабель старой схемы: среда не проверяется. Выберите конкретные профили и тип кабеля для физической проверки.';
}
